// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Rain".

Someone standing in the rain. If you make the window smaller,
you can move the person into the light.

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time

*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader, wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/3004455/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, .05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+wheel.y/1e3)
#define S smoothstep
#define SE(v,a) S(a+1./MN,a-1./MN,v)
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define bright vec3(.78,.79,.66)
#define dark vec3(.26,.34,.35)
float rnd(float p) {
	p=fract(p*.1031);
	p*=p+p*33.33;
	p*=p+p;
	return fract(p);
}
float rnd(vec2 a) {
	vec3 p=fract(a.xyx*.1031);
	p+=dot(p,p.yzx+33.33);
	return fract((p.x+p.y)*p.z);
}
float rain(vec2 p) {
	p.y+=T*2.;
	p.xy*=60.;
	p.y+=rnd(floor(p.x))*80.;
	return clamp(1.-length(vec2(cos(p.x*3.2),sin(p.y*.1)-1.7)),.0,1.);
}
vec3 figure(vec2 uv, float k, out float d) {
	vec3 col=vec3(0);
	vec2 p=uv;
	p.x-=.05*sin(p.y*12.+1.2*cos(p.y*4.-2.5));
	p.y-=clamp(p.y,-.4,.2);
	d=length(p);
	d=SE(d,.01+.003*sin(1.+uv.y*12.+1.2*cos(uv.y*4.-2.5)-.125*(2.5+uv.y*2.-T*20.)));
	p=uv;
	p.x+=.04*sin(p.y*22.);
	p.y-=clamp(p.y,-.4,.2);
	float e=length(p);
	e=SE(e,.01+.004*sin(uv.y*22.-.125*(uv.y*2.-T*20.)));
	d=max(d,e);
	p=uv;
	p.y-=.28;
	e=length(p);
	e=SE(e,.04+.003*sin(uv.y*12.-T));
	d=max(d,e);
	col=mix(col,mix(dark,bright,k),d);
	return col;
}
vec2 mask(vec2 uv, float t) {
	float size=5., w=uv.y*10.;
	vec2 aspect=vec2(2,1);
	uv*=size*aspect;
	uv.y+=t;
	vec2 gv=fract(uv)-.5, id=floor(uv);
	float n=rnd(id), x=(n-.5)*.8;
	x+=(.4-abs(x))*sin(3.*w)*pow(sin(w),6.)*.45;
	t+=n*6.28318;
	float y=-sin(t+sin(t+sin(t)*.5))*.45;
	y-=pow(gv.x-x,2.);
	vec2 dp=(gv-vec2(x,y))/aspect, tp=(gv-vec2(x,T*.25))/aspect;
	float drop=SE(length(dp),.04);
	tp.y=(fract(tp.y*8.)-.5)/8.;
	float trail=SE(length(tp),.02)*S(-.05,.05,dp.y)*S(.5,y,gv.y);
	return drop*dp+tp*trail+.01*SE(abs(dp.x),.05)*tp;
}
vec3 cc(vec3 col, float a, float b) {
	float f=dot(col,bright);
	return mix(col,col*.0+f*a,f*b);
}
void main() {
	vec2 uv=FC/R.y, p=uv;
	uv-=2.4*min(min(1.5*mask(uv+1.2,T*2.),2.*mask(uv*1.2,T*1.2)),mask(uv*2.,T));
	float flash=sin(T*sin(3.2+T*10.))*pow(max(sin(T+sin(T)),.0),10.);
	uv+=mix(.0,mix(.0,5e-3,flash),sin(uv.x*1200.)-sin(uv.y*800.));
	float w=clamp(uv.x,-.5,.5);
	vec3 col=mix(dark,bright,mix(.0,.5,uv.y-cos(.25*sin(T*2.-w*12.)-w*12.)));
	float d, rel=R.x/R.y;
	vec2 z=FC/R;
	z.x*=rel;
	z.x-=rel;
	z*=2.;
	z+=vec2(.6,-.42);
	col=mix(col,figure(z,w*sin(uv.y*11.+4.+w*2.*sin(T+uv.y)),d),d);
	col=mix(col,mix(col,bright,.7*rain(p*vec2(8,-2))),clamp(1.-p.y*18.,.0,1.));
	col=mix(col,mix(col,dark,.8*rain(p*vec2(8,-4)*rot(-.5))),clamp(1.-p.y*8.,.0,1.));
	for (float i=.0; i<9.; i++) {
	  uv.xy*=rot(sin(i*.2)*3e-4+sin(T)*9e-5)*1.08;
	  uv.xy+=rnd(i)*vec2(.95,1.05);
	  col+=i/30.*rain(uv)*(p.y+.2);
	}
	col=cc(col,.6*(1.+flash),.3*(1.+flash))*(1.+flash);
	col=S(.0,1.,col);
	O=vec4(col,1);
}

